 function fallbackGuitar(){if(!ctx)return;ctx.clearRect(0,0,width,height);const left=width*.06,right=width*.94,top=height*.39,h=Math.min(height*.37,240),fx=f=>left+(1-2**(-f/12))*2*(right-left),sy=s=>top+(5-s)*h/5;const g=ctx.createLinearGradient(0,top,0,top+h);g.addColorStop(0,'#201815');g.addColorStop(.5,'#463125');g.addColorStop(1,'#201815');ctx.fillStyle=g;ctx.fillRect(left-20,top-25,right-left+40,h+50);for(let f=0;f<=12;f++){ctx.fillStyle=f?'#9c9b8b':'#e5d6b3';ctx.fillRect(fx(f),top-13,f?2:5,h+26);if(showLabels)text(String(f),f?((fx(f-1)+fx(f))/2):left-13,top-31,'#8e948d',10);}for(let s=0;s<6;s++){ctx.strokeStyle=s<3?'#baa27c':'#b9bfbd';ctx.lineWidth=s<3?2:1;ctx.beginPath();ctx.moveTo(left-12,sy(s));ctx.lineTo(right+12,sy(s));ctx.stroke();if(showLabels)text(String(6-s),left-30,sy(s),'#8e948d',11);}for(const n of [...active,...manual.filter(n=>n.until>performance.now()).map(n=>n.event)]){const x=n[5]?(fx(n[5])+fx(n[5]-1))/2:left-10;ctx.fillStyle='#e1bb7d';ctx.beginPath();ctx.arc(x,sy(n[4]),height<600?9:13,0,Math.PI*2);ctx.fill();if(showLabels)text(String(n[5]),x,sy(n[4]),'#3a2b1d',height<600?9:11);}}
 let pointer=null;const ray=new THREE.Raycaster();ray.params.Line={threshold:.05};
 function inputAt(e){if(renderer){const r=container.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/width*2-1,-(e.clientY-r.top)/height*2+1),camera);if(instrument==='piano'){const hit=ray.intersectObjects(keyTargets)[0];if(hit)return {midi:hit.object.userData.midi};}else{const hit=ray.intersectObject(guitar.hit)[0];if(hit)return guitar.input(guitar.group.worldToLocal(hit.point));}}else if(instrument==='piano'){const top=height*.48,keyH=height*.34;if(e.clientY<top||e.clientY>top+keyH)return;const w=width*.94/whiteCount;for(const black of [true,false])for(const [m,k] of keys)if(k.black===black&&Math.abs(e.clientX-k.fallbackX)<w*(black?.29:.49)&&e.clientY<top+keyH*(black?.63:1))return {midi:m};}else{const left=width*.06,right=width*.94,top=height*.39,h=Math.min(height*.37,240);if(e.clientY<top-15||e.clientY>top+h+15||e.clientX<left-18||e.clientX>right)return;const string=Math.max(0,Math.min(5,5-Math.round((e.clientY-top)/(h/5))));let fret=0;while(fret<12&&e.clientX>left+(1-2**(-fret/12))*2*(right-left)+3)fret++;return {midi:openStrings[string]+fret,string,fret};}}
 container.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,drag:false};container.setPointerCapture?.(e.pointerId);});container.addEventListener('pointermove',e=>{if(!pointer)return;const dx=e.clientX-pointer.x;if(Math.abs(dx)>5){pointer.drag=true;pan-=dx/width*(instrument==='piano'?keyboardWidth:7.8)/zoom;pointer.x=e.clientX;cameraPose();}});container.addEventListener('pointerup',e=>{if(pointer&&!pointer.drag){const hit=inputAt(e);if(hit)onInput(hit);}pointer=null;});container.addEventListener('pointercancel',()=>pointer=null);
 let last=performance.now(),running=true;function frame(t){if(!running)return;const dt=Math.min(.05,(t-last)/1000);last=t;manual=manual.filter(n=>n.until>performance.now());if(renderer)render3D(dt,t);else if(instrument==='piano')fallbackPiano();else fallbackGuitar();requestAnimationFrame(frame);}requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{running=!document.hidden;if(running){last=performance.now();requestAnimationFrame(frame);}});
 return {is3D:Boolean(renderer),setInstrument(v){instrument=v;manual=[];pan=v==='guitar'?-.45:0;if(renderer){piano.visible=v==='piano';guitar.group.visible=v==='guitar';}cameraPose();},setRange(min,max){const r=[Math.max(21,Math.floor(min/12)*12),Math.min(108,Math.floor(max/12)*12+11)];if(r[0]===range[0]&&r[1]===range[1])return;range=r;if(instrument==='piano')pan=0;buildPiano();cameraPose();},setFrame(frame){position=frame.position;notes=frame.notes;active=frame.active;next=frame.next;},setCamera(v){view=v;cameraPose();},setZoom(v){zoom=v;cameraPose();},setLabels(v){showLabels=v;},setPreview(v){showPreview=v;},setTheme(v){light=v;if(renderer)renderer.toneMappingExposure=v?1.5:1.3;},press(event){manual.push({event,until:performance.now()+650});if(instrument==='guitar')guitar?.pluck(event[4]);},resize};
